 function analysisFeedback(cam){const record=cameraFeedbackFor(cam),draft=feedbackDraft?.key===cameraReviewKey(cam)?feedbackDraft:null,radio=(name,value,label,selected)=>`<label><input type="radio" name="${name}" value="${value}" ${selected===value?'checked':''}>${label}</label>`;return `<section class="camera-analysis-feedback" data-feedback-camera="${escape(cam.id)}" aria-label="个人版分析反馈"><p class="camera-feedback-context">个人版 · ${feedbackStatusLabel(record.status)}</p>${draft?`<form data-map-form="analysis-feedback" data-camera-id="${escape(cam.id)}" novalidate><fieldset><legend>反馈意见 <span>必选</span></legend><div class="camera-feedback-options">${radio('decision','reject','不采纳',draft.decision)}${radio('decision','no_value','相机无价值',draft.decision)}</div>${draft.errors.decision?`<p class="camera-feedback-error" role="alert">${escape(draft.errors.decision)}</p>`:''}</fieldset><fieldset><legend>反馈原因 <span>必选</span></legend><div class="camera-feedback-options">${radio('reason','tuple','相机五元组信息错误',draft.reason)}${radio('reason','other','其他原因',draft.reason)}</div>${draft.errors.reason?`<p class="camera-feedback-error" role="alert">${escape(draft.errors.reason)}</p>`:''}</fieldset><label class="camera-feedback-details" ${draft.reason==='other'?'':'hidden'}><span>其他原因 <small>必填</small></span><textarea name="details" rows="2" maxlength="300" aria-label="其他反馈原因" aria-invalid="${!!draft.errors.details}" placeholder="请说明具体原因">${escape(draft.details)}</textarea>${draft.errors.details?`<span class="camera-feedback-error" role="alert">${escape(draft.errors.details)}</span>`:''}</label><p class="camera-feedback-note">反馈针对本次 AI 分析，提交后保留当前挂载决定。</p><div class="camera-feedback-actions"><button type="button" class="button small ghost" data-map="feedback-cancel" data-id="${escape(cam.id)}">取消</button><button type="submit" class="button small primary">提交反馈</button></div></form>`:record.status!=='pending'?`<div class="camera-feedback-summary" role="status"><strong>${feedbackDecisionLabel(record.decision)}</strong><span>${feedbackReasonLabel(record.reason)}${record.details?'：'+escape(record.details):''}</span></div>`:''}</section>`}
 function refreshAnalysisFeedback(cam,focus=''){
  let overlay=document.querySelector('.camera-feedback-overlay');
  if(!feedbackDraft){overlay?.remove();document.body.classList.remove('camera-feedback-open');document.getElementById('app').inert=false;document.querySelectorAll(`[data-map="feedback-open"][data-id="${CSS.escape(cam.id)}"]`).forEach(button=>button.textContent=feedbackTriggerLabel(cam));document.querySelector(`[data-map="feedback-open"][data-id="${CSS.escape(cam.id)}"]`)?.focus({preventScroll:true});return}
  if(!overlay){overlay=document.createElement('div');overlay.className='camera-feedback-overlay';overlay.innerHTML=`<section class="camera-feedback-dialog" role="dialog" aria-modal="true" aria-labelledby="camera-feedback-title"><header><div><h2 id="camera-feedback-title">分析反馈</h2><p>${escape(cam.name)} · ${escape(cam.id)}</p></div><button type="button" class="camera-feedback-close" data-map="feedback-cancel" data-id="${escape(cam.id)}" aria-label="关闭分析反馈">×</button></header>${analysisFeedback(cam)}</section>`;document.body.append(overlay);document.body.classList.add('camera-feedback-open');document.getElementById('app').inert=true}else overlay.querySelector('[data-feedback-camera]').outerHTML=analysisFeedback(cam);
  if(focus)overlay.querySelector(focus)?.focus({preventScroll:true});
 }
 document.addEventListener('click',event=>{if(!event.target.matches?.('.camera-feedback-overlay'))return;const cam=currentFeedbackCamera(event.target.querySelector('[data-feedback-camera]').dataset.feedbackCamera);if(cam){feedbackDraft=null;refreshAnalysisFeedback(cam)}});
 document.addEventListener('keydown',event=>{const overlay=document.querySelector('.camera-feedback-overlay');if(!overlay)return;if(event.key==='Escape'){event.preventDefault();event.stopImmediatePropagation();const cam=currentFeedbackCamera(overlay.querySelector('[data-feedback-camera]').dataset.feedbackCamera);feedbackDraft=null;refreshAnalysisFeedback(cam);return}if(event.key==='Tab'){const items=[...overlay.querySelectorAll('button,input,textarea')],first=items[0],last=items.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}},true);
 document.addEventListener('click',event=>{const button=event.target.closest?.('[data-map="feedback-open"],[data-map="feedback-cancel"]');if(!button)return;event.preventDefault();const cam=currentFeedbackCamera(button.dataset.id);if(!cam)return;if(button.dataset.map==='feedback-open'){const record=cameraFeedbackFor(cam);feedbackDraft={key:cameraReviewKey(cam),decision:record.decision||'',reason:record.reason||'',details:record.details||'',errors:{}};refreshAnalysisFeedback(cam,'input[name="decision"]')}else{feedbackDraft=null;refreshAnalysisFeedback(cam,'[data-map="feedback-open"]')}});
 document.addEventListener('change',event=>{const form=event.target.closest?.('[data-map-form="analysis-feedback"]');if(!form||!feedbackDraft||!event.target.matches('input[type="radio"]'))return;const cam=currentFeedbackCamera(form.dataset.cameraId);if(!cam||feedbackDraft.key!==cameraReviewKey(cam))return;feedbackDraft[event.target.name]=event.target.value;delete feedbackDraft.errors[event.target.name];refreshAnalysisFeedback(cam,`input[name="${event.target.name}"][value="${CSS.escape(event.target.value)}"]`)});
 document.addEventListener('input',event=>{if(event.target.matches?.('[data-map-form="analysis-feedback"] textarea')&&feedbackDraft)feedbackDraft.details=event.target.value});
 document.addEventListener('submit',event=>{const form=event.target;if(form.dataset.mapForm!=='analysis-feedback')return;event.preventDefault();const cam=currentFeedbackCamera(form.dataset.cameraId);if(!cam||feedbackDraft?.key!==cameraReviewKey(cam))return;const values=Object.fromEntries(new FormData(form)),errors={};if(!values.decision)errors.decision='请选择反馈意见';if(!values.reason)errors.reason='请选择反馈原因';if(values.reason==='other'&&!String(values.details||'').trim())errors.details='请填写其他原因，不能仅包含空格';feedbackDraft={...feedbackDraft,...values,errors};if(Object.keys(errors).length){const name=Object.keys(errors)[0];refreshAnalysisFeedback(cam,name==='details'?'textarea':`input[name="${name}"]`);return}try{saveCameraAnalysisFeedback(cam,values);feedbackDraft=null;refreshAnalysisFeedback(cam,'[data-map="feedback-open"]');notify('个人版分析反馈已保存')}catch(error){notify('反馈未保存：'+error.message)}});
 function mountPlaceCard(cam,poi,kind,index){const selected=ui.camera.selectedPoiId===poi.id,point=position(cam),record=rec(cam),candidate=(record.candidates||[]).some(item=>item.id===poi.id),coverKind=poi.category==='停车场'?'parking':poi.category==='景点'?'park':'camera',evidence=kind==='nearby'||kind==='all'&&!candidate?null:poiEvidence(cam,poi),status=kind==='pre'?'AI 预挂建议 · 待确认':kind==='nearby'?'附近 · 未匹配':kind==='all'?candidate?'候选 · 尚未挂载':'目录 POI · 未匹配':'候选 · 尚未挂载',cardClass=`map-shortlist mount-place-card ${kind==='nearby'?'nearby-option':''} ${kind==='pre'?'pre-option':''} ${kind==='all'?'directory-option':''}`;return `<div class="${cardClass}"><div class="mount-place-overview"><button type="button" class="mount-poi-cover" data-map="preview-poi-cover" data-id="${escape(poi.id)}" aria-label="放大查看${escape(poi.name)}封面"><img src="${sceneImageSource(coverKind).split('/').pop()}" alt="${escape(poi.name)}类型封面示意" loading="lazy"><span>点击放大</span></button><button type="button" role="radio" aria-checked="${selected}" aria-label="${escape(poi.name)} · ${escape(status)} · ${distanceText(point,poiPoint(poi))}" tabindex="${selected||index===0?'0':'-1'}" class="mount-place-select" data-map="select-shortlist" data-id="${escape(poi.id)}"><span class="map-radio-mark" aria-hidden="true"></span><span class="map-shortlist-copy"><strong>${escape(poi.name)}</strong><small>${escape(poiLabel(poi))} · ${escape(poi.district)} · ${distanceText(point,poiPoint(poi))}${poi.localMountSample?' · 本机新建':''}</small><span class="map-choice-status">${status}</span></span></button></div>${evidence?`<div class="mount-place-evidence"><span class="mount-evidence-title">候选依据</span><span class="analysis-evidence-signals">${evidence.signals.map(([label,tone])=>tag(label,tone)).join('')}</span><span class="mount-evidence-copy">${escape(evidence.reason)}</span>${evidence.caution?`<span class="mount-evidence-caution">${escape(evidence.caution)}</span>`:''}</div>`:''}</div>`}
 function cameraCoverPreview(cam){const poi=cityPois().find(item=>item.id===ui.camera.coverPreviewPoiId);if(!poi)return '';const coverKind=poi.category==='停车场'?'parking':poi.category==='景点'?'park':'camera';return `<div class="mount-image-lightbox" data-map="close-cover-preview" role="presentation"><section class="mount-image-preview" role="dialog" aria-modal="true" aria-label="${escape(poi.name)}封面预览"><header><div><strong>${escape(poi.name)}</strong><small>${escape(poi.category)} · 封面示意</small></div><button type="button" class="button small ghost" data-map="close-cover-preview" aria-label="关闭封面预览">关闭</button></header><img src="${sceneImageSource(coverKind).split('/').pop()}" alt="${escape(poi.name)}封面放大预览"><p>本机示例封面图</p></section></div>`}

 const treeMarkup=(mode)=>{
  const s=ui[mode],pois=mode==='poi'?poiOpsPois():cityPois();if(!pois.length)return '<div class="map-empty">当前城市和项目范围内没有匹配的 POI</div>';
  const matching=poi=>mode!=='poi'||pois.includes(poi);
  const roots=pois.filter(poi=>!poi.parentId||!pois.some(parent=>parent.id===poi.parentId));
  const node=(poi,parent=false,expanded=true)=>{const button=`<button class="map-tree-node ${s.poiId===poi.id?'selected':''} ${parent?'tree-parent':''}" data-map="select-poi" data-id="${escape(poi.id)}" aria-pressed="${s.poiId===poi.id}"><span class="tree-node-mark">${parent?'':'·'}</span><span class="tree-node-copy"><strong>${escape(poi.name)}</strong><small>${escape(poi.category)} · ${escape(poi.district)}</small>${mode==='camera'?`<em>范围内 ${inAoiMountCameras(poi).length} 台相机</em>`:''}</span></button>`;return parent?`<div class="map-tree-parent-row">${button}<button class="map-tree-expand" data-map="toggle-tree" data-id="${escape(poi.id)}" aria-label="${expanded?'收起':'展开'}${escape(poi.name)}子级" aria-expanded="${expanded}">${expanded?'⌄':'›'}</button></div>`:button};
  return `<div class="map-tree-group"><div class="map-tree-caption">${escape(mode==='poi'?poiCityInfo().name+' · '+poiCityProjects().length+' 个授权项目':currentProject()?.name||info().name+' POI')}</div>${roots.map(parent=>{const children=pois.filter(poi=>poi.parentId===parent.id),parentMatches=matching(parent)||children.some(matching),expanded=s.expanded?.[parent.id]!==false;if(!parentMatches)return '';return `${node(parent,children.length>0,expanded)}${children.length&&expanded?`<div class="map-tree-children">${children.filter(matching).map(p=>node(p)).join('')}</div>`:''}`}).join('')}</div>`;
 };
