 function mountWorkflowRail(cam){const s=ui.camera,step=s.workflowStep||1,saved=s.completedCameraId===cam.id,selected=cityPois().find(poi=>poi.id===s.selectedPoiId),items=mountProjectCams(),index=items.findIndex(item=>item.id===cam.id);return `<footer class="mount-workflow-rail" aria-label="相机挂载步骤操作"><div class="mount-rail-progress"><strong>${saved?'挂载完成':`第 ${index+1} / ${items.length} 台`}</strong><span>${saved?'已保存相机信息与挂载关系':step===3?'挂载关系待保存':hasCameraProfileChanges(cam)?'草稿未保存':'核对后继续'}</span></div><div class="mount-rail-actions">${s.unableOpen?`<form class="mount-unable-rail" data-map-form="unable"><label>无法挂载原因<input name="reason" required aria-label="无法挂载原因" value="${escape(s.reason)}"></label><button type="button" class="button ghost" data-map="toggle-unable">取消</button><button class="button primary">保存标记</button></form>`:saved?`<button class="button ghost" data-map="queue-return">返回待挂载列表</button><button class="button primary" data-map="next-camera" ${nextUnprocessedId(cam)?'':'disabled'}>处理下一台</button>`:s.poiCreateOpen?'':`<button class="button ghost" data-map="${step>1?'mount-step-back':'toggle-unable'}">${step>1?'返回修改':'标记无法挂载'}</button><button class="button primary" data-map="${step===3?'save-mount':'mount-step-next'}" data-id="${escape(selected?.id||'')}" ${step>1&&!selected?'disabled':''}>${step===1?'下一步：选择 POI':step===2?'确认挂载':'保存挂载'}</button>`}</div></footer>`}
