 function poiDisplayInfo(p){const sample=['p1','p2','p3'].includes(p.id),kind=p.category==='停车场'?'parking':p.category==='景点'?'park':'camera',text=value=>typeof value==='string'?value:'',photo=Array.isArray(p.photos)?p.photos.find(item=>item?.url)?.url:'',phone=text(p.tel||p.phone||p.telephone||p.contactPhone),cost=text(p.biz_ext?.cost);return {cover:text(p.coverImage||p.coverUrl||p.cover)||photo||(sample?sceneImageSource(kind):''),phone:phone||(sample?(poiCityKey()==='hz'?'0571':poiCityKey()==='sh'?'021':'0512')+'-0000-010'+p.id.slice(1):''),fee:text(p.feeInfo||p.feeDescription||p.fee||p.priceDescription)||(cost?'人均消费 '+cost+' 元':sample?(p.category==='停车场'?'停车收费：首小时 6 元，后续每小时 4 元':'免费开放'):'')}}
 function poiCameraCards(cameras,p){return cameras.map(cam=>{const mountedId=poiOpsMountId(cam),relation=mountedId===p.id?'已挂载至本 POI'+(poiOpsContains(position(cam),p)?'':' · AOI 范围外'):mountedId?'已挂载至 '+(poiCityPois().find(item=>item.id===mountedId)?.name||mountedId):'尚未挂载';return `<article class="poi-mounted-card"><div class="poi-mounted-thumb">${image(cam)}</div><div><strong>${escape(cam.name)}</strong><small>${escape(cam.projectName)}</small><span class="poi-camera-value-status ${poiStatusTone(poiOpsStatus(cam))}">${poiStatusLabel(poiOpsStatus(cam))}</span><small>${escape(relation)}</small><button type="button" data-map="poi-camera-detail" data-id="${escape(cam.id)}">查看相机详情</button></div></article>`}).join('')}
