 function analysisStreet(cam){return String(cam.installationPosition||'').split(' · ')[0]||'未登记'}
 const analysisProfileKey='seetime-personal-analysis-profiles-v1',analysisProfileOptions={scene:['城市道路','公共空间','公共休闲空间','步行区域','停车场','车辆通行空间'],tags:['车辆','行人','泊位','游客','非机动车'],elements:['人流','车流','车位','排队']};
 function analysisProfileStore(){try{return JSON.parse(localStorage.getItem(analysisProfileKey)||'{}')}catch{return {}}}
 function analysisProfileStorageKey(cam){const project=visibleProjects().find(item=>item.id===cam?.projectId)||currentProject();return `${project?.cityKey||store.session.city}:${project?.id||''}:${cam?.id||''}`}
 function analysisProfileDraftValues(values){return (values||[]).filter(value=>value&&value!=='待分析')}
 function analysisProfileEdit(cam){const profile=analysisProfile(cam);ui.analysis.profileDraft={key:analysisProfileStorageKey(cam),cameraId:cam.id,tags:analysisProfileDraftValues(profile.tags),elements:analysisProfileDraftValues(profile.elements)}}
 function analysisProfileDropdown(field,label,options,selected){const summary=selected.length?selected.join('、'):`请选择${label}`;return `<fieldset class="analysis-profile-field" data-profile-field="${field}"><legend>${label}</legend><details class="analysis-profile-dropdown"><summary><span data-profile-summary>${escape(summary)}</span><small>多选</small><i aria-hidden="true">⌄</i></summary><div class="analysis-profile-options" role="group" aria-label="${label}，可多选">${options.map(value=>`<label><input type="checkbox" data-analysis-profile-option="${field}" value="${escape(value)}" ${selected.includes(value)?'checked':''}><span>${escape(value)}</span></label>`).join('')}</div></details></fieldset>`}
 function normaliseProfileTags(values){return [...new Set(values.map(value=>String(value).trim()).filter(Boolean))]}
 function analysisProfileEditor(cam){const draft=ui.analysis.profileDraft,profile=analysisProfile(cam);return `<form class="analysis-profile-editor" data-map-form="analysis-profile"><div class="analysis-profile-editor-head"><h3>相机元素与检测要素</h3></div><div class="analysis-summary-row profile-scene-readonly"><span class="analysis-summary-label">画面描述 · 只读</span><span>${escape(profile.scene||'待补充')}</span></div><fieldset class="analysis-profile-field profile-text-tags"><legend>相机元素</legend><div class="profile-tag-inputs">${draft.tags.map((value,index)=>`<div class="profile-tag-token"><input type="text" data-profile-tag-input="${index}" aria-label="元素 ${index+1}" value="${escape(value)}" placeholder="输入元素" style="width:${Math.max(6,value.length*2+2)}ch"><button type="button" data-map="analysis-tag-remove" data-id="${index}" aria-label="删除元素 ${escape(value||String(index+1))}">×</button></div>`).join('')}<button type="button" class="profile-tag-add" data-map="analysis-tag-add">＋ 添加元素</button></div><small class="profile-tag-help">直接修改文字；可添加或删除元素。</small></fieldset>${analysisProfileDropdown('elements','检测要素',analysisProfileOptions.elements,draft.elements)}<div class="analysis-profile-editor-actions"><button type="button" class="button small ghost" data-map="analysis-profile-cancel" data-id="${escape(cam.id)}">取消</button><button type="button" class="button small primary" data-map="analysis-profile-save" data-id="${escape(cam.id)}">保存相机信息</button></div></form>`}
 function saveAnalysisProfile(cam){const draft=ui.analysis.profileDraft;if(!draft||draft.key!==analysisProfileStorageKey(cam))return false;const form=document.querySelector('.analysis-profile-editor'),read=field=>[...form.querySelectorAll(`[data-analysis-profile-option="${field}"]:checked`)].map(input=>input.value),next={scene:analysisProfile(cam).scene,tags:normaliseProfileTags(draft.tags),elements:read('elements')},all=analysisProfileStore();all[analysisProfileStorageKey(cam)]=next;localStorage.setItem(analysisProfileKey,JSON.stringify(all));ui.analysis.profileDraft=null;render();requestAnimationFrame(()=>{const scroll=document.querySelector('.mount-card-scroll');if(scroll)scroll.scrollTop=0;document.querySelector('[data-map="analysis-profile-edit"]')?.focus({preventScroll:true})});notify('相机元素与检测要素已保存到本机示例数据');return true}

 function analysisProfile(cam){
  const saved=cam&&analysisProfileStore()[analysisProfileStorageKey(cam)];if(saved)return {scene:String(saved.scene||''),tags:Array.isArray(saved.tags)?saved.tags:[],elements:Array.isArray(saved.elements)?saved.elements:[]};
  // Fixed camera samples remain independent of candidate and mount decisions.
  if(cam?.demoProfile)return cam.demoProfile;
  const samples=[{scene:'城市道路、公共空间',tags:['车辆','行人'],elements:['车流','人流']},{scene:'公共休闲空间、步行区域',tags:['游客','行人'],elements:['人流','排队']},{scene:'停车场、车辆通行空间',tags:['车辆','泊位','行人'],elements:['车位','车流','人流']}],index=Math.max(0,Number(cam.id.match(/(\d+)$/)?.[1]||1)-1);return cam.analysisState==='待分析'?{scene:'待分析',tags:['待分析'],elements:['待分析']}:samples[index%samples.length]
 }
 function analysisMountedPois(cam){const r=rec(cam);return [...new Set(r.mounts.filter(id=>r.sources?.[id]==='manual'))].map(id=>cityPois().find(poi=>poi.id===id)||{id,name:id,category:'资料待完善',district:''})}
 function analysisQuery(cam){const s=ui.analysis,q=s.listQuery.trim().toLowerCase(),tagQuery=s.tagQuery.trim().toLowerCase(),poiQuery=String(s.poiQuery||'').trim().toLowerCase(),f=s.filters,profile=analysisProfile(cam);return (!q||`${cam.name} ${cam.id}`.toLowerCase().includes(q))&&(!tagQuery||profile.tags.some(tag=>tag.toLowerCase().includes(tagQuery)))&&(!poiQuery||analysisMountedPois(cam).some(poi=>poi.name.toLowerCase().includes(poiQuery)))&&(f.city==='all'||f.city===store.session.city)&&(f.district==='all'||cam.district===f.district)&&(f.street==='all'||analysisStreet(cam)===f.street)&&(f.element==='all'||profile.elements.includes(f.element))}
 function analysisCameras(){return mountProjectCams().filter(cam=>analysisMountedPois(cam).length&&analysisQuery(cam))}
 function analysisPoiMatches(poi){const s=ui.analysis,q=s.search.trim().toLowerCase();return (!q||`${poi.name} ${poi.id}`.toLowerCase().includes(q))&&(s.district==='all'||poi.district===s.district)}
 function analysisPoiFilterActive(){return ui.analysis.district!=='all'||!!ui.analysis.search.trim()}
 function analysisMapBaseCameras(){const selected=cityPois().find(p=>p.id===ui.analysis.poiId);if(selected)return projectCams().filter(cam=>isInAoi(cam,selected));if(analysisPoiFilterActive()){const pois=cityPois().filter(analysisPoiMatches);return projectCams().filter(cam=>pois.some(poi=>isInAoi(cam,poi)))}return projectCams()}
 function analysisMapCameras(){return analysisMapBaseCameras().filter(cam=>cameraVisible(cam,ui.analysis))}
 function pruneAnalysisCamera(){const pool=analysisCameras();if(ui.analysis.cameraId&&!pool.some(cam=>cam.id===ui.analysis.cameraId))ui.analysis.cameraId=''}
 function selectAnalysisCamera(id){feedbackDraft=null;const pool=analysisCameras();if(!pool.some(cam=>cam.id===id))return;if(ui.analysis.cameraId===id){ui.analysis.cameraId='';ui.analysis.profileDraft=null;render();requestAnimationFrame(()=>(document.querySelector(`[data-map="analysis-camera"][data-id="${CSS.escape(id)}"], [data-camera-id="${CSS.escape(id)}"]`)||document.querySelector('.analysis-list-filters input[name="q"]'))?.focus({preventScroll:true}));return}ui.analysis.profileDraft=null;ui.analysis.cameraId=id;ui.analysis.frameSlot='morning';render();requestAnimationFrame(()=>document.querySelector('.analysis-detail-panel .analysis-close')?.focus({preventScroll:true}))}
 function selectAnalysisPoi(id){const poi=cityPois().find(p=>p.id===id);if(!poi)return;ui.analysis.poiId=ui.analysis.poiId===id?'':id;if(poi.parentId)ui.analysis.expanded[poi.parentId]=true;pruneAnalysisCamera();render()}
 function setAnalysisMode(mode){ui.analysis.mode=mode==='map'?'map':'list';pruneAnalysisCamera();render()}
 function analysisTree(){const s=ui.analysis,pois=cityPois();if(!pois.length)return '<div class="map-empty">暂无 POI 示例数据</div>';const visible=poi=>analysisPoiMatches(poi)||pois.some(child=>child.parentId===poi.id&&analysisPoiMatches(child));const roots=pois.filter(poi=>!poi.parentId||!pois.some(parent=>parent.id===poi.parentId));const node=(poi,parent=false,expanded=true)=>{const count=inAoiCameras(poi).length,button=`<button class="map-tree-node ${s.poiId===poi.id?'selected':''} ${parent?'tree-parent':''}" data-map="analysis-poi" data-id="${escape(poi.id)}" aria-pressed="${s.poiId===poi.id}"><span class="tree-node-mark">${parent?'':'·'}</span><span class="tree-node-copy"><strong>${escape(poi.name)}</strong><small>${escape(poi.category)} · ${escape(poi.district)}</small><em>范围内 ${count} 台相机</em></span></button>`;return parent?`<div class="map-tree-parent-row">${button}<button class="map-tree-expand" data-map="analysis-toggle" data-id="${escape(poi.id)}" aria-label="${expanded?'收起':'展开'}${escape(poi.name)}子级" aria-expanded="${expanded}">${expanded?'⌄':'›'}</button></div>`:button};return `<div class="map-tree-group"><div class="map-tree-caption">${escape(currentProject()?.name||'')} · POI 树</div>${roots.map(parent=>{if(!visible(parent)&&!pois.some(child=>child.parentId===parent.id&&visible(child)))return '';const children=pois.filter(poi=>poi.parentId===parent.id&&visible(poi)),expanded=s.expanded?.[parent.id]!==false;return `${visible(parent)?node(parent,true,expanded):''}${children.length&&expanded?`<div class="map-tree-children">${children.map(p=>node(p)).join('')}</div>`:''}`}).join('')}</div>`}
 function analysisFrames(cam,single=false,mode='analysis'){const slots=[['morning','早','08:00'],['noon','中','13:00'],['evening','晚','19:00']];if(single){const [slot,label,time]=slots.find(([id])=>id===ui[mode==='mount'?'camera':'analysis'].frameSlot)||slots[0];return `<section class="analysis-slots analysis-single-slots" aria-label="早中晚分析帧"><div class="analysis-frame-heading"><h3>分析画面</h3><div class="analysis-frame-tabs" role="tablist" aria-label="分析画面时段">${slots.map(([id,name,clock])=>`<button type="button" role="tab" id="${mode}-frame-tab-${id}" data-map="${mode}-frame" data-id="${id}" aria-selected="${id===slot}" aria-controls="${mode}-frame-panel">${name} <span>${clock}</span></button>`).join('')}</div></div><figure id="${mode}-frame-panel" class="analysis-single-frame analysis-slot-${slot}" role="tabpanel" aria-labelledby="${mode}-frame-tab-${slot}"><div class="analysis-frame">${image(cam)}<span class="analysis-frame-time">${time} ${label}</span></div></figure><p class="analysis-frame-note">画面与封面为示意，分析内容可在挂载页核对编辑。</p></section>`}return `<section class="analysis-slots" aria-label="早中晚分析帧"><h3>分析画面</h3><div class="analysis-slot-row">${slots.map(([slot,label,time])=>`<figure class="analysis-slot analysis-slot-${slot}"><div class="analysis-frame">${image(cam)}<span class="analysis-frame-time">${time} ${label}</span></div><figcaption class="sr-only">${label} ${time}</figcaption></figure>`).join('')}</div><p class="analysis-frame-note">AI 生成示意图，非现场实时录像</p></section>`}
 function poiEvidence(cam,poi){
  const profile=analysisProfile(cam);
  const point=position(cam),meters=distance(point,poiPoint(poi)),nameMatch=!!cam.name&&cam.name.includes(poi.name),installationMatch=!!cam.installationPosition&&cam.installationPosition.includes(poi.name),watermarkMatch=!!cam.cameraWatermark&&cam.cameraWatermark.includes(poi.name),sceneMatch=poi.category==='停车场'?profile.scene.includes('停车场'):poi.category==='景点'?/休闲|步行/.test(profile.scene):/公共空间|步行/.test(profile.scene),kind=poi.category==='停车场'?'parking':poi.category==='景点'?'park':'camera';
  const signals=[[meters!=null?'距相机 '+distanceText(point,poiPoint(poi)):'距离未知',meters!=null?'recommend':'neutral'],[sceneMatch?'画面描述可关联':'画面描述待核对',sceneMatch?'confirmed':'pending'],[nameMatch?'相机名命中':'相机名未命中',nameMatch?'confirmed':'neutral'],[installationMatch?'安装位置命中':cam.installationPosition?'安装位置未命中':'安装位置未登记',installationMatch?'confirmed':'neutral'],[watermarkMatch?'水印命中':cam.cameraWatermark?'水印未命中':'水印未登记',watermarkMatch?'confirmed':'neutral'],['画面文字待核验','neutral']],reason=sceneMatch?`画面描述「${profile.scene}」与地点类型「${poiLabel(poi)}」可关联，坐标距离作为辅助线索。`:`本机画面元素为「${profile.tags.join('、')}」，与地点类型「${poiLabel(poi)}」的对应关系仍需核对。`;
  return {signals,reason,caution:!nameMatch&&!watermarkMatch&&!installationMatch?'名称、安装位置和水印均无直接对应证据，需人工核验。':''}
 }
 function analysisArchive(cam,closable=false){
  const point=position(cam),profile=analysisProfile(cam);
  const basicFacts=[['相机名称',cam.name],['相机编号',cam.id],['相机水印',cam.cameraWatermark||'未登记'],['所属项目',currentProject()?.name||''],['经纬度 · GCJ-02',point?point.map(n=>n.toFixed(6)).join(', '):'位置待完善']],factRows=items=>items.map(([label,value])=>`<div><dt>${escape(label)}</dt><dd>${escape(value)}</dd></div>`).join('');
     const mounted=analysisMountedPois(cam),detailFacts=`<dl class="analysis-facts">${factRows(basicFacts)}</dl>`,readoutMarkup=`<section class="analysis-readout"><h3>分析结果</h3><div class="analysis-summary-row"><span class="analysis-summary-label">画面描述</span><span>${escape(profile.scene||'待补充')}</span></div><div class="analysis-summary-row"><span class="analysis-summary-label">元素</span><div class="analysis-value-tags">${profile.tags.map(label=>tag(label,'neutral')).join('')||'<small>暂无元素</small>'}</div></div><div class="analysis-summary-row"><span class="analysis-summary-label">检测要素</span><div class="analysis-value-tags">${profile.elements.map(label=>tag(label,'recommend')).join('')||'<small>暂无检测要素</small>'}</div></div><div class="analysis-candidates analysis-mounted-poi"><h4>已挂载 POI <small>${mounted.length} 个</small></h4>${mounted.length?mounted.map(poi=>`<div class="analysis-mounted-place"><img src="${escape(poiDisplayInfo(poi).cover||sceneImageSource('park'))}" alt="${escape(poi.name)}封面"><div><strong>${escape(poi.name)}</strong><small>${escape(poi.category)} · ${escape(poi.district)}</small><span>已确认挂载</span></div></div>`).join(''):'<p class="map-empty-inline">暂无确认挂载关系</p>'}</div></section>`;
   return `<article class="analysis-archive"><div class="analysis-archive-head"><div class="analysis-camera-heading"><span class="analysis-camera-meta"><span class="mono">${escape(cam.id)}</span><span>${escape(cam.district||'区县待完善')}</span></span><h2>${escape(cam.name)}</h2><p class="analysis-camera-installation"><span>安装位置</span>${escape(cam.installationPosition||'待完善')}</p></div><div class="analysis-archive-tools">${analysisFeedbackTrigger(cam)}${closable?'<button type="button" class="analysis-close" data-map="analysis-close" aria-label="关闭相机详情">×</button>':''}</div></div>${analysisFrames(cam,true)}${parkingCalibrationControl(cam,false)}${readoutMarkup}<section class="analysis-archive-record"><h3>相机基本信息</h3>${detailFacts}</section></article>`
 }
 function analysisDetailPanel(cam,context='',withBackdrop=true){return `${withBackdrop?'<div class="camera-detail-backdrop" data-map="analysis-close" aria-hidden="true"></div>':''}<aside class="analysis-detail-panel ${context}" role="dialog" aria-modal="${withBackdrop}" aria-label="相机详情">${analysisArchive(cam,true)}</aside>`}
 function parkingCalibrationReadback(cam,data){const slots=data.slots||[];return `<section class="parking-saved-preview" aria-label="已保存车位标注"><div class="parking-saved-heading"><h3>车位标注</h3><span>已保存 · 只读</span></div><div class="parking-saved-metrics"><div><span>已绘制车位</span><strong>${slots.length}<small>个</small></strong></div><div><span>可见车位总数</span><strong>${data.total==null?'未登记':`${escape(data.total)}<small>个</small>`}</strong></div></div><figure class="parking-saved-frame"><img src="${escape(data.imageSrc||sceneImageSource(camFrameKindSafe(cam)))}" alt="${escape(cam.name)}已保存标注画面" loading="lazy"><svg class="parking-saved-svg" viewBox="0 0 1672 941" role="img" aria-label="${slots.length} 个车位轮廓">${calibrationSvg({slots,selected:-1,points:[]})}</svg></figure><p>按保存标注时的画面回显，车位编号与轮廓一一对应。</p></section>`}
 function parkingCalibrationControl(cam,editable=false){const data=parkingCalibration(cam);if(!editable&&data)return parkingCalibrationReadback(cam,data);if(!analysisProfile(cam).elements.includes('车位'))return '';const count=data?.slots?.length||0,total=data?.total||0;return `<section class="parking-calibration-summary"><div><strong>车位标注</strong><small>${count?`已绘制 ${count} 个车位 · 可见车位总数 ${total}`:'车位检测已启用；暂无可展示的车位区域/检测结果'}</small></div>${editable?`<button type="button" class="button small ghost" data-map="parking-calibration" data-id="${escape(cam.id)}">${count?'编辑标注':'开始标注'}</button>`:''}</section>`}

 function calibrationSvg(c){const pointsOf=points=>points.map(([x,y])=>`${x*1672},${y*941}`).join(' '),slots=c.slots.map((slot,index)=>{const center=slot.points.reduce((acc,[x,y])=>[acc[0]+x/slot.points.length,acc[1]+y/slot.points.length],[0,0]);return `<g class="parking-slot-shape ${index===c.selected?'selected':''}" data-calibration-slot="${index}"><polygon points="${pointsOf(slot.points)}"></polygon><text x="${center[0]*1672}" y="${center[1]*941}">P${String(index+1).padStart(2,'0')}</text>${index===c.selected?slot.points.map(([x,y],vertex)=>`<circle class="parking-slot-handle" data-slot-index="${index}" data-calibration-vertex="${vertex}" cx="${x*1672}" cy="${y*941}" r="10"></circle>`).join(''):''}</g>`}).join(''),draft=c.points.length?`<polyline class="parking-slot-draft" points="${pointsOf(c.points)}"></polyline>${c.points.map(([x,y])=>`<circle class="parking-slot-draft-point" cx="${x*1672}" cy="${y*941}" r="8"></circle>`).join('')}`:'';return slots+draft}
 function parkingCalibrationModal(){const c=ui.analysis.calibration;if(!c)return '';const cam=mountProjectCams().find(item=>item.id===c.cameraId);if(!cam)return '';return `<div class="parking-calibration-backdrop"><section class="parking-calibration-dialog" role="dialog" aria-modal="true" aria-labelledby="parking-calibration-title"><header><div><small>${escape(currentProject()?.name||'')} · ${escape(cam.id)}</small><h2 id="parking-calibration-title">${escape(cam.name)} · 车位标注</h2><p>在相机画面上逐个绘制车位。四次点击形成一个车位，可拖动顶点微调。</p></div><button type="button" class="parking-calibration-close" data-map="parking-calibration-close" aria-label="关闭车位标注">×</button></header><div class="parking-calibration-content"><div class="parking-calibration-stage" data-calibration-stage tabindex="0" aria-label="相机画面，点击四个角绘制车位"><img src="${sceneImageSource(camFrameKindSafe(cam))}" alt="${escape(cam.name)}画面"><svg class="parking-calibration-svg" viewBox="0 0 1672 941" preserveAspectRatio="none" aria-label="车位标注图层">${calibrationSvg(c)}</svg><span class="parking-calibration-badge">示意画面 · 非现场视频</span></div><aside class="parking-calibration-tools"><section><span class="parking-calibration-label">已绘制</span><strong>${c.slots.length} <small>个车位</small></strong><span class="parking-calibration-label">可见车位总数</span><label class="parking-count-field"><input type="number" min="${c.slots.length||1}" step="1" value="${escape(c.total)}" data-calibration-total aria-label="可见车位总数" aria-invalid="${c.totalError?'true':'false'}" aria-describedby="parking-calibration-message"><span>个</span></label><small class="parking-count-help">允许只绘制部分车位；总数需不少于已绘制数量。</small></section><div class="parking-calibration-actions"><button type="button" class="button small ghost" data-map="parking-calibration-add">新画车位</button><button type="button" class="button small ghost" data-map="parking-calibration-undo" ${c.points.length?'':'disabled'}>撤回顶点</button><button type="button" class="button small ghost" data-map="parking-calibration-delete" ${c.selected>=0?'':'disabled'}>删除选中</button></div><div class="parking-slot-list">${c.slots.map((slot,index)=>`<button type="button" class="parking-slot-row ${c.selected===index?'selected':''}" data-calibration-select="${index}"><span>P${String(index+1).padStart(2,'0')}</span><small>${c.selected===index?'已选中，可拖动角点':'点击画面可选中编辑'}</small></button>`).join('')||'<p>还没有已绘制车位</p>'}</div><p class="parking-calibration-message" id="parking-calibration-message" role="status">${escape(c.message||'先点击“新画车位”，再依次点击四个角。')}</p>${c.confirmLeave?'<div class="parking-calibration-confirm"><span>有未保存的修改</span><button type="button" class="button small ghost" data-map="parking-calibration-continue">继续编辑</button><button type="button" class="button small ghost" data-map="parking-calibration-leave">放弃修改</button></div>':''}<button type="button" class="button primary parking-calibration-save" data-map="parking-calibration-save">${c.pendingAction?(c.pendingAction.kind==='mount'?'保存标注并挂载':'保存标注并下一台'):'保存标注'}</button></aside></div></section></div>`}
 function openParkingCalibration(id,pendingAction=null){const cam=mountProjectCams().find(item=>item.id===id);if(!cam||!analysisProfile(cam).elements.includes('车位'))return;const saved=parkingCalibration(cam);ui.analysis.calibration={cameraId:id,projectId:cam.projectId,pendingAction,triggerAction:document.activeElement?.dataset.map||'parking-calibration',totalError:false,slots:copy(saved?.slots||[]),total:saved?.total||saved?.slots?.length||0,points:[],selected:-1,dirty:false,confirmLeave:false,message:pendingAction?'保存车位标注后'+(pendingAction.kind==='mount'?'确认挂载，仍停留当前相机。':'进入下一台相机。'):'先点击“新画车位”，再依次点击四个角。'};render();requestAnimationFrame(()=>document.querySelector('.parking-calibration-close')?.focus({preventScroll:true}))}
 function dismissParkingCalibration(){const trigger=ui.analysis.calibration?.triggerAction;ui.analysis.calibration=null;render();requestAnimationFrame(()=>(document.querySelector(`[data-map="${CSS.escape(trigger||'parking-calibration')}"]`)||document.querySelector('[data-map="parking-calibration"]')||document.querySelector('.mount-inspector .map-card-close'))?.focus({preventScroll:true}))}
 function closeParkingCalibration(){const c=ui.analysis.calibration;if(!c)return;if(c.dirty||c.points.length){c.confirmLeave=true;c.message='离开会放弃本次未保存的修改。';render();requestAnimationFrame(()=>document.querySelector('[data-map="parking-calibration-continue"]')?.focus({preventScroll:true}));return}dismissParkingCalibration()}
 function saveParkingCalibration(){const c=ui.analysis.calibration,cam=c&&mountProjectCams().find(item=>item.id===c.cameraId&&item.projectId===c.projectId);if(!c||!cam)return;const total=Number(c.total);if(c.points.length){c.message='请先完成当前车位的四个角，或撤回未完成顶点。';render();requestAnimationFrame(()=>document.querySelector('[data-calibration-stage]')?.focus({preventScroll:true}));return}if(!c.slots.length){c.message='至少绘制一个车位后才能保存。';render();requestAnimationFrame(()=>document.querySelector('[data-calibration-stage]')?.focus({preventScroll:true}));return}if(!Number.isInteger(total)||total<c.slots.length||total<1){c.totalError=true;c.message=`可见车位总数需为整数，且不少于已绘制的 ${c.slots.length} 个。`;render();requestAnimationFrame(()=>document.querySelector('[data-calibration-total]')?.focus({preventScroll:true}));return}try{const all=JSON.parse(localStorage.getItem(calibrationKey)||'{}');all[`${cam.projectId}:${cam.id}`]={imageSrc:sceneImageSource(camFrameKindSafe(cam)),slots:c.slots,total,updatedAt:new Date().toISOString()};localStorage.setItem(calibrationKey,JSON.stringify(all));c.dirty=false;c.message='标定已保存到本机示例数据。';const pending=c.pendingAction;ui.analysis.calibration=null;if(pending)executeMountAction(cam,pending);else render()}catch(error){c.message='保存失败：浏览器本机存储不可用。';render()}}
 function analysisModes(){const s=ui.analysis;return `<div class="analysis-modes"><button type="button" data-map="analysis-mode" data-id="list" aria-pressed="${s.mode==='list'}">相机列表</button><button type="button" data-map="analysis-mode" data-id="map" aria-pressed="${s.mode==='map'}">地图</button></div>`}
 function analysisFilterForm(){const s=analysisFilterDraft(),f=s.filters,cams=mountProjectCams().filter(confirmed),cities=[...new Set(visibleProjects().map(project=>project.cityKey))],locationInfo=CITY_INFO[f.city==='all'?store.session.city:f.city]||info(),districts=f.city==='all'||f.city===store.session.city?[...new Set(cams.map(cam=>cam.district).filter(Boolean))]:locationInfo.districts,streets=f.city==='all'||f.city===store.session.city?[...new Set(cams.map(analysisStreet).filter(Boolean))]:locationInfo.locations,cityLabel=key=>CITY_INFO[key]?.name||key,select=(label,name,value,options)=>`<label class="analysis-filter-field"><span>${label}</span><select name="${name}" data-analysis-list-filter="${name}" aria-label="${label}"><option value="all" ${value==='all'?'selected':''}>全部</option>${options.map(([key,text])=>`<option value="${escape(key)}" ${value===key?'selected':''}>${escape(text)}</option>`).join('')}</select></label>`;
     return `<form class="analysis-list-filters" data-map-form="analysis-search">${select('城市','city',f.city,cities.map(key=>[key,cityLabel(key)]))}${select('区县','district',f.district,districts.map(name=>[name,name]))}${select('街道','street',f.street,streets.map(name=>[name,name]))}${select('检测要素','element',f.element,['人流','车流','车位','排队'].map(name=>[name,name]))}<label class="analysis-filter-field analysis-name-filter"><span>相机名称 / ID</span><input name="q" value="${escape(s.listQuery)}" placeholder="输入名称或 ID 模糊检索" aria-label="相机名称或 ID"></label><label class="analysis-filter-field analysis-tag-filter"><span>元素</span><input name="tags" value="${escape(s.tagQuery)}" placeholder="输入元素模糊检索" aria-label="元素模糊检索"></label><label class="analysis-filter-field analysis-poi-name-filter"><span>已挂载 POI</span><input name="poi" value="${escape(s.poiQuery||'')}" placeholder="输入 POI 名称模糊检索" aria-label="已挂载 POI 名称"></label><div class="analysis-filter-actions"><button class="button small ghost" type="button" data-map="analysis-search-reset">重置</button><button class="button small primary" type="submit">检索</button></div></form>`
 }
 function analysisListPage(){const s=ui.analysis,cams=analysisCameras(),cam=cams.find(item=>item.id===s.cameraId),districtCount=new Set(cams.map(item=>item.district).filter(Boolean)).size,cityMismatch=s.filters.city!=='all'&&s.filters.city!==store.session.city,emptyMessage=cityMismatch?`当前项目属于${info().name}，请切换到对应城市项目查看相机。`:'当前条件下没有已挂载相机，请调整筛选，或在个人版相机挂载中确认地点。',headers=['相机名称 / 编号','检测要素','元素','已挂载 POI','画面描述'];const body=cams.length?cams.map(c=>{const profile=analysisProfile(c),mounted=analysisMountedPois(c);return `<tr class="${c.id===s.cameraId?'is-selected':''}" data-map="analysis-camera" data-id="${escape(c.id)}" tabindex="0"><td><span class="analysis-camera-cell"><strong>${escape(c.name)}</strong><small class="mono">${escape(c.id)}</small></span></td><td><div class="analysis-value-tags">${profile.elements.map(value=>tag(value,'recommend')).join('')||'—'}</div></td><td><div class="analysis-value-tags">${profile.tags.map(value=>tag(value,'neutral')).join('')||'—'}</div></td><td><div class="analysis-poi-labels">${mounted.map(poi=>`<span>${escape(poi.name)}</span>`).join('')}</div>${mounted.length>1?`<small class="analysis-poi-count">${mounted.length} 个已挂载 POI</small>`:''}</td><td>${escape(profile.scene||'待补充')}</td></tr>`}).join(''):`<tr><td colspan="5"><div class="empty">${emptyMessage}</div></td></tr>`;return `${analysisFilterForm()}<div class="analysis-list-shell"><div class="analysis-list-grid ${cam?'has-detail':''}"><section class="box analysis-list-main"><div class="table-wrap analysis-table"><table><thead><tr>${headers.map(h=>`<th scope="col">${h}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div><div class="table-end"><span>${cams.length} 台已挂载相机 · 覆盖 ${districtCount} 个区县</span></div></section>${cam?analysisDetailPanel(cam,'analysis-list-panel',false):''}</div></div>`}
 function analysisMapPage(){const s=ui.analysis,cams=analysisMapCameras(),cam=cams.find(item=>item.id===s.cameraId),poi=cityPois().find(item=>item.id===s.poiId);const filters=[['unmounted','未挂载','unmounted-dot'],['hasCandidate','有候选','has-candidate-dot'],['aiPre','AI 预挂','pre-dot'],['mounted','已挂载','mounted-dot'],['noCandidate','无候选','no-candidate-dot']];const title=poi?`${poi.name} · AOI 范围`:analysisPoiFilterActive()?'筛选后的地点范围':'当前项目相机';return `<div class="analysis-list-toolbar">${analysisModes()}</div><section class="analysis-layout"><aside class="analysis-rail" aria-label="POI 筛选"><form data-map-form="analysis-poi-filter" class="analysis-poi-filters"><input name="q" value="${escape(s.search)}" placeholder="筛选 POI 名称" aria-label="筛选 POI 名称"><select name="district" data-analysis-filter="district" aria-label="区县"><option value="all">全部区县</option>${info().districts.map(d=>`<option value="${escape(d)}" ${s.district===d?'selected':''}>${escape(d)}</option>`).join('')}</select><button type="submit">筛选</button></form><div class="analysis-scroll">${analysisTree()}</div></aside><div class="map-main-stage analysis-map-stage"><div id="map-ops-canvas" class="map-ops-canvas" tabindex="-1" aria-label="相机分析地图"></div><div id="map-ops-status" class="map-load-status"><strong>正在加载地图…</strong></div><div class="map-inline-title"><strong>${escape(title)}</strong><small>${cams.length} 台相机</small></div><div class="map-layer-toggles">${filters.map(([k,label,tone])=>`<label title="${k==='hasCandidate'?'未挂载且有候选地点':'显示或隐藏该状态相机'}"><input type="checkbox" data-analysis-layer="${k}" ${s.layers[k]?'checked':''}><i class="layer-dot ${tone}"></i>${label}</label>`).join('')}</div>${cam?analysisDetailPanel(cam,'analysis-map-panel'):'<div class="analysis-map-hint">点击地图上的相机，查看档案</div>'}</div></section>`}
 function analysisPage(){return analysisListPage()}
 function baseNavigate(route,tab){base.navigate(route,tab)}
 projectAnalysisPage=function(){return analysisPage()};bindingsPage=function(){return cameraPage()};cityPoiPage=function(){return poiPage()};
 moduleWorkspace=function(content){if(['projectAnalysis','bindings','personalProfile'].includes(state.route)&&!state.detail)return content;return base.moduleWorkspace(content)};
 function applyAnalysisProjectContext(){document.body.classList.toggle('personal-operations-active',['bindings','projectAnalysis','personalProfile'].includes(state.route));const active=!['projects','workspace','operations'].includes(state.route)&&!!currentProject();document.body.classList.toggle('project-context-condensed',active);if(['bindings','projectAnalysis','personalProfile'].includes(state.route)){const actions=document.querySelector('.top-actions');if(actions&&!actions.querySelector('.demo-tag'))actions.insertAdjacentHTML('afterbegin','<span class="demo-tag">本机示例</span>')}if(active){const label=document.querySelector('.workspace-context .context-select>span');if(label){label.textContent='当前执行项目';label.nextElementSibling?.setAttribute('aria-label','当前执行项目')}}}
 navigate=function(route,tab=''){if(requestCameraLeave(()=>navigate(route,tab)))return;feedbackDraft=null;ui.analysis.profileDraft=null;ui.analysis.calibration=null;if(active())destroyMap();if(route==='projectAnalysis')ui.analysis={mode:'list',poiId:'',cameraId:'',search:'',listQuery:'',tagQuery:'',poiQuery:'',frameSlot:'morning',sceneOpen:false,filters:{city:'all',district:'all',street:'all',scenes:[],element:'all'},expanded:{},layers:{unmounted:true,hasCandidate:true,aiPre:true,mounted:true,noCandidate:true}};return baseNavigate(route,tab)};
 const mapRoute=()=>state.route==='bindings'||state.route==='personalProfile'||(state.route==='projectAnalysis'&&ui.analysis.mode==='map');
 render=function(){const inspector=document.querySelector('.mount-inspector'),scroll=inspector?.querySelector('.mount-card-scroll'),mountScroll=inspector?.dataset.mountCameraId===ui.camera.cameraId?scroll?.scrollTop||0:0,restoreMountScroll=()=>{const next=document.querySelector('.mount-inspector .mount-card-scroll');if(next)next.scrollTop=mountScroll};if(mapRoute()&&!state.detail){const previous=captureMapView();destroyMap();base.render();restoreMountScroll();applyAnalysisProjectContext();document.body.classList.toggle('camera-drawer-open',!!document.querySelector('.camera-detail-backdrop'));document.querySelector('.analysis-detail-panel')?.style.setProperty('transform','translateZ(0)');if(mapRoute()&&!!currentProject())mountMap(previous);return}destroyMap();base.render();restoreMountScroll();applyAnalysisProjectContext();document.body.classList.toggle('camera-drawer-open',!!document.querySelector('.camera-detail-backdrop'));document.querySelector('.analysis-detail-panel')?.style.setProperty('transform','translateZ(0)')};
 dispatchAction=function(actionName,id=''){if(actionName==='ops-poi-camera'){const [projectId,cameraId,poiId]=id.split(':');if(projectId&&cameraId){state.projectId=projectId;store.session.city=PROJECTS.find(p=>p.id===projectId)?.cityKey||store.session.city;persistSession?.();openCamera(cameraId,poiId);return true}}return base.dispatchAction(actionName,id)};
 openFrameworkDetail=function(route,id){if(isActive()&&route==='personalProfile'){selectPoi(id);return true}return base.openFrameworkDetail(route,id)};
 function hasMountDraftChanges(){const draft=ui.analysis.profileDraft,cam=draft&&mountProjectCams().find(cam=>cam.id===draft.cameraId);return !!(cam&&hasCameraProfileChanges(cam))||!!ui.camera.selectedPoiId||!!ui.camera.poiCreateOpen&&(!!ui.camera.poiCreateName.trim()||!!ui.camera.poiCreatePoint)||!!ui.analysis.calibration?.dirty||ui.camera.unableOpen&&!!ui.camera.reason.trim()}
 function discardMountDraft(){ui.analysis.calibration=null;ui.analysis.profileDraft=null;ui.camera.selectedPoiId='';ui.camera.poiCreateOpen=false;ui.camera.poiCreatePicking=false;ui.camera.poiCreatePoint=null;ui.camera.poiCreateName='';ui.camera.poiCreateAddress='';ui.camera.unableOpen=false;ui.camera.reason='';ui.camera.reasonError=''}
 function resetProjectContext(){destroyMap();feedbackDraft=null;ui.camera=copy(initialCamera);ui.poi=copy(initialPoi);ui.analysis=copy(initialAnalysis);pendingCamera='';pendingPoi='';aoiPoi=''}
 window.SeeTimeMapOps={analysisProfile,hasDraftChanges:hasMountDraftChanges,discardDraft:discardMountDraft,resetProjectContext,selectPoi,selectCamera,openCamera,refresh:()=>render(),snapshot:()=>copy(ui),inAoiCameras,poiPoint,position};
 window.addEventListener('resize',()=>{if(!map||!mapSdk||!isActive())return;requestAnimationFrame(()=>{if(map&&mapSdk&&isActive()){const previous=captureMapView();map.resize();drawMap(mapSdk);if(previous?.context===mapViewContext()){map.setZoom(previous.zoom);map.setCenter(previous.center)}}})});
 render();
